// Shape of src/data/cases/<project>.json (generated by tools/build_cases.py from Figma)
export type Run = {
  text: string; fam: string; w: number; it: boolean; size: number; color: string;
  lh: string | number; // "a" = auto, number = px, "120%" = percent
  ls: string | number; // 0, px, or "-2%"
};
export type TextLine = { runs: Run[]; list: boolean };
export type TextNode = {
  x: number; y: number; w: number; h: number;
  align: "left" | "center" | "right" | "justify";
  resize: "H" | "W" | "N"; // auto-height, auto-width, fixed
  size: number; lines: TextLine[]; card: number | null; href?: string;
};
export type Card = { fill: string; op: number; x: number; y: number; w: number; h: number };
export type FrameImage = { x: number; y: number; w: number; h: number; src: string; card: number | null };
export type CaseFrameData = {
  id: string; h: number; visual: boolean; bg: string; title: string;
  nodes: TextNode[]; cards: Card[]; images: FrameImage[];
};
export type CaseData = { slug: string; frames: CaseFrameData[] };
